import type { DateColumnType, Duration, Record } from '../../db'

/**
 * @description Defines the parameters for the WaitForADuration flow logic.
 * @property {string} duration - The duration to wait. The format depends on the durationType.
 * @property {'explicit_duration' | 'relative_duration' | 'percentage_duration'} durationType - Specifies the type of duration.
 * @property {Record<'cmn_schedule'> | string} [schedule] - An optional schedule for the wait. This can be a reference to a schedule record or a string.
 * @property {string} [annotation] - An optional annotation for this step.
 * @property {string} [relativeOperator] - Operator for relative duration (e.g., 'plus', 'minus').
 * @property {string} [relativeDatetime] - Reference datetime for relative duration.
 * @property {number} [percentage] - Percentage value for percentage-based duration.
 * @property {string} [percentageDatetime] - Reference datetime for percentage-based duration.
 */
type ExplicitDurationParams = {
    durationType: 'explicit_duration'
    duration: Duration
    schedule?: Record<'cmn_schedule'> | string
    annotation?: string
    /** UUID for referencing this instance's outputs as datapills */
    uuid?: string
}

type RelativeDurationParams = {
    durationType: 'relative_duration'
    duration: Duration
    relativeOperator: 'before' | 'after'
    relativeDatetime: string
    schedule?: Record<'cmn_schedule'> | string
    annotation?: string
    /** UUID for referencing this instance's outputs as datapills */
    uuid?: string
}

type PercentageDurationParams = {
    durationType: 'percentage_duration'
    percentage: number
    percentageDatetime: string
    schedule?: Record<'cmn_schedule'> | string
    annotation?: string
    /** UUID for referencing this instance's outputs as datapills */
    uuid?: string
}

export type WaitForADurationParams = Now.Internal.WithID<
    ExplicitDurationParams | RelativeDurationParams | PercentageDurationParams
>

/**
 * Output values from the WaitForADuration flow logic.
 * These outputs can be referenced as datapills in subsequent steps.
 */
export type WaitForADurationOutputs = {
    /** The total duration that was waited (duration format string) */
    total_duration: Duration
    /** The scheduled end date/time when the wait completed */
    // TODO: Use DateTimeColumnType when available
    scheduled_end_date_time: DateColumnType
}

/**
 * @description Pauses the flow for a specified duration.
 * @param {WaitForADurationParams} params - The parameters for the wait action.
 * @returns An object containing outputs that can be used as datapills:
 *   - total_duration: The total duration that was waited
 *   - scheduled_end_date_time: The scheduled end date/time when the wait completed
 */
export declare function WaitForADuration(params: WaitForADurationParams): WaitForADurationOutputs
